package com.barrowstunnelskilltracker;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import java.util.Collection;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class BarrowsTunnelsKillTrackerChestOverlay extends Overlay
{
    private static final int WARNING_TILE_REGION_X = 31;
    private static final int WARNING_TILE_REGION_Y = 30;

    private static final Color CHEST_GREEN = new Color(0xFF26FF00, true);
    private static final Color CHEST_GREEN_FILL = new Color(0x3826FF00, true);
    private static final Color CHEST_RED = new Color(255, 0, 0);
    private static final Color CHEST_RED_FILL = new Color(255, 0, 0, 45);
    private static final Color WARNING_RED = new Color(255, 0, 0);
    private static final Color WARNING_RED_FILL = new Color(255, 0, 0, 45);
    private static final String WARNING_TEXT = "Need more KC";

    private final Client client;
    private final BarrowsTunnelsKillTrackerPlugin plugin;
    private final BarrowsTunnelsKillTrackerConfig config;

    @Inject
    private BarrowsTunnelsKillTrackerChestOverlay(
        Client client,
        BarrowsTunnelsKillTrackerPlugin plugin,
        BarrowsTunnelsKillTrackerConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showChestWarning() || !plugin.isInChestRoom())
        {
            return null;
        }

        boolean quotaSatisfied =
            plugin.isQuotaMet() || plugin.isRewardPotentialMaxed();

        renderChestHighlight(graphics, quotaSatisfied);

        if (!quotaSatisfied)
        {
            renderWarningTile(graphics);
        }

        return null;
    }

    private void renderChestHighlight(Graphics2D graphics, boolean quotaSatisfied)
    {
        GameObject chest = plugin.getBarrowsChest();

        if (chest == null)
        {
            return;
        }

        Color outlineColor = quotaSatisfied ? CHEST_GREEN : CHEST_RED;
        Color fillColor = quotaSatisfied ? CHEST_GREEN_FILL : CHEST_RED_FILL;

        Shape clickbox = chest.getClickbox();

        if (clickbox != null)
        {
            OverlayUtil.renderPolygon(
                graphics,
                clickbox,
                outlineColor,
                fillColor,
                new BasicStroke(2)
            );
            return;
        }

        Polygon tilePolygon = chest.getCanvasTilePoly();

        if (tilePolygon != null)
        {
            OverlayUtil.renderPolygon(
                graphics,
                tilePolygon,
                outlineColor,
                fillColor,
                new BasicStroke(2)
            );
        }
    }

    private void renderWarningTile(Graphics2D graphics)
    {
        WorldPoint warningWorldPoint = WorldPoint.fromRegion(
            BarrowsTunnelsKillTrackerPlugin.BARROWS_TUNNELS_REGION_ID,
            WARNING_TILE_REGION_X,
            WARNING_TILE_REGION_Y,
            plugin.getCurrentPlane()
        );

        Collection<WorldPoint> localWorldPoints =
            WorldPoint.toLocalInstance(client, warningWorldPoint);

        for (WorldPoint localWorldPoint : localWorldPoints)
        {
            LocalPoint localPoint = LocalPoint.fromWorld(client, localWorldPoint);

            if (localPoint == null)
            {
                continue;
            }

            Polygon polygon = Perspective.getCanvasTilePoly(client, localPoint);

            if (polygon != null)
            {
                OverlayUtil.renderPolygon(
                    graphics,
                    polygon,
                    WARNING_RED,
                    WARNING_RED_FILL,
                    new BasicStroke(2)
                );
            }

            Point textLocation = Perspective.getCanvasTextLocation(
                client,
                graphics,
                localPoint,
                WARNING_TEXT,
                35
            );

            if (textLocation != null)
            {
                OverlayUtil.renderTextLocation(
                    graphics,
                    textLocation,
                    WARNING_TEXT,
                    WARNING_RED
                );
            }

            break;
        }
    }
}

package com.barrowstunnelskilltracker;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(BarrowsTunnelsKillTrackerConfig.GROUP)
public interface BarrowsTunnelsKillTrackerConfig extends Config
{
    String GROUP = "barrowsTunnelsKillTracker";

    @ConfigItem(
        keyName = "showOverlay",
        name = "Show overlay",
        description = "Display the current Barrows run's tunnel kill counts and kill-plan progress",
        position = 0
    )
    default boolean showOverlay()
    {
        return true;
    }

    @ConfigItem(
        keyName = "highlightTargets",
        name = "Highlight required NPCs",
        description = "Highlight NPC types until their configured kill-count target is met",
        position = 1
    )
    default boolean highlightTargets()
    {
        return true;
    }

    @Alpha
    @ConfigItem(
        keyName = "highlightColor",
        name = "Highlight colour",
        description = "Colour used to outline NPCs still required by the kill plan",
        position = 2
    )
    default Color highlightColor()
    {
        return new Color(0x26FF00);
    }

    @ConfigItem(
        keyName = "showChestWarning",
        name = "Chest quota warning",
        description = "Highlight the reward chest and warn when the configured kill quota has not been met",
        position = 3
    )
    default boolean showChestWarning()
    {
        return true;
    }

    @Range(min = 0, max = 50)
    @ConfigItem(
        keyName = "bloodwormTarget",
        name = "Bloodworm target",
        description = "Target number of Bloodworms",
        position = 10
    )
    default int bloodwormTarget()
    {
        return 1;
    }

    @Range(min = 0, max = 50)
    @ConfigItem(
        keyName = "cryptRatTarget",
        name = "Crypt rat target",
        description = "Target number of Crypt rats",
        position = 11
    )
    default int cryptRatTarget()
    {
        return 0;
    }

    @Range(min = 0, max = 50)
    @ConfigItem(
        keyName = "giantCryptRatTarget",
        name = "Giant crypt rat target",
        description = "Target number of Giant crypt rats",
        position = 12
    )
    default int giantCryptRatTarget()
    {
        return 0;
    }

    @Range(min = 0, max = 50)
    @ConfigItem(
        keyName = "cryptSpiderTarget",
        name = "Crypt spider target",
        description = "Target number of Crypt spiders",
        position = 13
    )
    default int cryptSpiderTarget()
    {
        return 0;
    }

    @Range(min = 0, max = 50)
    @ConfigItem(
        keyName = "giantCryptSpiderTarget",
        name = "Giant crypt spider target",
        description = "Target number of Giant crypt spiders",
        position = 14
    )
    default int giantCryptSpiderTarget()
    {
        return 0;
    }

    @Range(min = 0, max = 50)
    @ConfigItem(
        keyName = "skeletonTarget",
        name = "Skeleton target",
        description = "Target number of Skeletons",
        position = 15
    )
    default int skeletonTarget()
    {
        return 2;
    }
}

package com.barrowstunnelskilltracker;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.NPC;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

class BarrowsTunnelsKillTrackerNpcOverlay extends Overlay
{
    private static final int OUTLINE_WIDTH = 2;
    private static final int OUTLINE_FEATHER = 1;

    private final BarrowsTunnelsKillTrackerPlugin plugin;
    private final BarrowsTunnelsKillTrackerConfig config;
    private final ModelOutlineRenderer modelOutlineRenderer;

    @Inject
    private BarrowsTunnelsKillTrackerNpcOverlay(
        BarrowsTunnelsKillTrackerPlugin plugin,
        BarrowsTunnelsKillTrackerConfig config,
        ModelOutlineRenderer modelOutlineRenderer)
    {
        this.plugin = plugin;
        this.config = config;
        this.modelOutlineRenderer = modelOutlineRenderer;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.highlightTargets() || !plugin.isInBarrowsTunnels())
        {
            return null;
        }

        for (NPC npc : plugin.getTrackedNpcs())
        {
            if (npc == null || npc.isDead())
            {
                continue;
            }

            TrackedNpc trackedNpc = TrackedNpc.fromNpcId(npc.getId());

            if (trackedNpc == null || !plugin.isTargetIncomplete(trackedNpc))
            {
                continue;
            }

            modelOutlineRenderer.drawOutline(
                npc,
                OUTLINE_WIDTH,
                config.highlightColor(),
                OUTLINE_FEATHER
            );
        }

        return null;
    }
}

package com.barrowstunnelskilltracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

class BarrowsTunnelsKillTrackerOverlay extends OverlayPanel
{
    private static final Color COMPLETE_COLOR = new Color(0, 255, 0);
    private static final Color INCOMPLETE_COLOR = Color.WHITE;

    private final BarrowsTunnelsKillTrackerPlugin plugin;
    private final BarrowsTunnelsKillTrackerConfig config;

    @Inject
    private BarrowsTunnelsKillTrackerOverlay(
        BarrowsTunnelsKillTrackerPlugin plugin,
        BarrowsTunnelsKillTrackerConfig config)
    {
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showOverlay() || !plugin.isInBarrowsRegion())
        {
            return null;
        }

        panelComponent.getChildren().add(
            TitleComponent.builder()
                .text("Barrows Tunnel Kills")
                .build()
        );

        boolean hasConfiguredTarget = false;

        for (TrackedNpc trackedNpc : TrackedNpc.values())
        {
            int target = plugin.getTarget(trackedNpc);

            if (target <= 0)
            {
                continue;
            }

            hasConfiguredTarget = true;

            int current = plugin.getKillCount(trackedNpc);

            panelComponent.getChildren().add(
                LineComponent.builder()
                    .left(trackedNpc.getDisplayName())
                    .right(current + "/" + target)
                    .rightColor(getProgressColor(current, target))
                    .build()
            );
        }

        if (!hasConfiguredTarget)
        {
            panelComponent.getChildren().add(
                LineComponent.builder()
                    .left("Kill plan")
                    .right("No targets")
                    .build()
            );
        }

        return super.render(graphics);
    }

    private Color getProgressColor(int current, int target)
    {
        if (current >= target)
        {
            return COMPLETE_COLOR;
        }

        return INCOMPLETE_COLOR;
    }
}

package com.barrowstunnelskilltracker;

import com.google.inject.Provides;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.Varbits;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
    name = "Barrows Tunnels Kill Tracker",
    description = "Tracks tunnel NPC kills and custom kill-plan progress during Barrows chest runs",
    tags = {"barrows", "kill count", "tracker", "pvm"}
)
public class BarrowsTunnelsKillTrackerPlugin extends Plugin
{
    static final int BARROWS_SURFACE_REGION_ID = 14131;
    static final int BARROWS_TUNNELS_REGION_ID = 14231;
    static final int BARROWS_CHEST_CLOSED_OBJECT_ID = 20723;
    static final int BARROWS_CHEST_OPEN_OBJECT_ID = 20724;
    static final int BARROWS_CHEST_CLOSED_EXAMINE_ID = 20973;
    static final int BARROWS_CHEST_OPEN_EXAMINE_ID = 20974;

    private static final int CHEST_ROOM_MIN_X = 26;
    private static final int CHEST_ROOM_MAX_X = 37;
    private static final int CHEST_ROOM_MIN_Y = 25;
    private static final int CHEST_ROOM_MAX_Y = 36;
    private static final String KILL_COUNTS_CONFIG_KEY = "killCounts";

    private final Map<TrackedNpc, Integer> killCounts = new EnumMap<>(TrackedNpc.class);
    private final Set<NPC> trackedNpcs = new HashSet<>();
    private final Set<NPC> engagedNpcs = new HashSet<>();
    private boolean rewardCollected;
    private GameObject barrowsChest;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ConfigManager configManager;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private BarrowsTunnelsKillTrackerOverlay overlay;

    @Inject
    private BarrowsTunnelsKillTrackerNpcOverlay npcOverlay;

    @Inject
    private BarrowsTunnelsKillTrackerChestOverlay chestOverlay;

    @Inject
    private BarrowsTunnelsKillTrackerConfig config;

    @Provides
    BarrowsTunnelsKillTrackerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(BarrowsTunnelsKillTrackerConfig.class);
    }

    @Override
    protected void startUp()
    {
        resetCounts();
        trackedNpcs.clear();
        engagedNpcs.clear();
        rewardCollected = false;
        barrowsChest = null;

        clientThread.invokeLater(this::loadPersistedKillCounts);

        overlayManager.add(overlay);
        overlayManager.add(npcOverlay);
        overlayManager.add(chestOverlay);

        log.debug("Barrows Tunnels Kill Tracker started");
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(chestOverlay);
        overlayManager.remove(npcOverlay);
        overlayManager.remove(overlay);

        trackedNpcs.clear();
        engagedNpcs.clear();
        resetCounts();
        rewardCollected = false;
        barrowsChest = null;

        log.debug("Barrows Tunnels Kill Tracker stopped");
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            trackedNpcs.clear();
            engagedNpcs.clear();
            rewardCollected = false;
            barrowsChest = null;
            loadPersistedKillCounts();
        }
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event)
    {
        GameObject gameObject = event.getGameObject();

        if (!isBarrowsChest(gameObject))
        {
            return;
        }

        barrowsChest = gameObject;
    }

    @Subscribe
    public void onGameObjectDespawned(GameObjectDespawned event)
    {
        if (event.getGameObject() == barrowsChest)
        {
            barrowsChest = null;
        }
    }

    @Subscribe
    public void onNpcSpawned(NpcSpawned event)
    {
        NPC npc = event.getNpc();

        if (TrackedNpc.fromNpcId(npc.getId()) != null)
        {
            trackedNpcs.add(npc);
        }
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event)
    {
        NPC npc = event.getNpc();

        trackedNpcs.remove(npc);
        boolean wasEngaged = engagedNpcs.remove(npc);

        if (rewardCollected
            || !npc.isDead()
            || !isInBarrowsTunnels()
            || !wasEngaged)
        {
            return;
        }

        TrackedNpc trackedNpc = TrackedNpc.fromNpcId(npc.getId());
        if (trackedNpc != null)
        {
            killCounts.merge(trackedNpc, 1, Integer::sum);
            persistKillCounts();
        }
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        /*
         * The reward interface identifies the local player's Barrows chest
         * opening. Scene-object chest state can be affected by other players.
         */
        if (event.getGroupId() == InterfaceID.BARROWS_REWARD)
        {
            resetForCollectedReward();
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        findLoadedBarrowsChest();

        Player localPlayer = client.getLocalPlayer();

        /*
         * Remember tracked NPCs that the local player has actually engaged.
         * Requiring engagement prevents nearby players' kills and ordinary
         * NPC despawns from increasing this plugin's kill counts.
         */
        if (!rewardCollected && localPlayer != null && isInBarrowsTunnels())
        {
            for (NPC npc : trackedNpcs)
            {
                if (npc.getInteracting() == localPlayer
                    || localPlayer.getInteracting() == npc)
                {
                    engagedNpcs.add(npc);
                }
            }
        }

        /*
         * Ignore lingering corpse despawns after the chest is opened.
         * Counting resumes after the player leaves the tunnels.
         */
        if (rewardCollected && !isInBarrowsTunnels())
        {
            rewardCollected = false;
            trackedNpcs.clear();
            engagedNpcs.clear();
        }
    }

    int getKillCount(TrackedNpc trackedNpc)
    {
        return killCounts.getOrDefault(trackedNpc, 0);
    }

    int getTarget(TrackedNpc trackedNpc)
    {
        switch (trackedNpc)
        {
            case BLOODWORM:
                return config.bloodwormTarget();
            case CRYPT_RAT:
                return config.cryptRatTarget();
            case GIANT_CRYPT_RAT:
                return config.giantCryptRatTarget();
            case CRYPT_SPIDER:
                return config.cryptSpiderTarget();
            case GIANT_CRYPT_SPIDER:
                return config.giantCryptSpiderTarget();
            case SKELETON:
                return config.skeletonTarget();
            default:
                return 0;
        }
    }

    boolean isTargetIncomplete(TrackedNpc trackedNpc)
    {
        int target = getTarget(trackedNpc);
        return target > 0 && getKillCount(trackedNpc) < target;
    }

    boolean isRewardPotentialMaxed()
    {
        return client.getVarbitValue(Varbits.BARROWS_REWARD_POTENTIAL) >= 1000;
    }

    boolean isQuotaMet()
    {
        for (TrackedNpc trackedNpc : TrackedNpc.values())
        {
            if (isTargetIncomplete(trackedNpc))
            {
                return false;
            }
        }

        return true;
    }

    Set<NPC> getTrackedNpcs()
    {
        return Collections.unmodifiableSet(trackedNpcs);
    }

    GameObject getBarrowsChest()
    {
        return barrowsChest;
    }

    private boolean isBarrowsChest(GameObject gameObject)
    {
        if (gameObject == null)
        {
            return false;
        }

        int objectId = gameObject.getId();

        return objectId == BARROWS_CHEST_CLOSED_OBJECT_ID
            || objectId == BARROWS_CHEST_OPEN_OBJECT_ID
            || objectId == BARROWS_CHEST_CLOSED_EXAMINE_ID
            || objectId == BARROWS_CHEST_OPEN_EXAMINE_ID;
    }

    private void findLoadedBarrowsChest()
    {
        if (!isInChestRoom())
        {
            barrowsChest = null;
            return;
        }

        Tile[][][] tiles = client.getScene().getTiles();
        int plane = client.getPlane();

        if (tiles == null || plane < 0 || plane >= tiles.length)
        {
            return;
        }

        for (Tile[] tileRow : tiles[plane])
        {
            if (tileRow == null)
            {
                continue;
            }

            for (Tile tile : tileRow)
            {
                if (tile == null)
                {
                    continue;
                }

                for (GameObject gameObject : tile.getGameObjects())
                {
                    if (!isBarrowsChest(gameObject))
                    {
                        continue;
                    }

                    barrowsChest = gameObject;

                    return;
                }
            }
        }

        barrowsChest = null;
    }

    boolean isInBarrowsRegion()
    {
        int regionId = getCurrentRegionId();

        return regionId == BARROWS_SURFACE_REGION_ID
            || regionId == BARROWS_TUNNELS_REGION_ID;
    }

    boolean isInBarrowsTunnels()
    {
        return getCurrentRegionId() == BARROWS_TUNNELS_REGION_ID;
    }

    boolean isInChestRoom()
    {
        WorldPoint location = getCurrentWorldLocation();

        return location != null
            && location.getRegionID() == BARROWS_TUNNELS_REGION_ID
            && location.getRegionX() >= CHEST_ROOM_MIN_X
            && location.getRegionX() <= CHEST_ROOM_MAX_X
            && location.getRegionY() >= CHEST_ROOM_MIN_Y
            && location.getRegionY() <= CHEST_ROOM_MAX_Y;
    }

    int getCurrentPlane()
    {
        WorldPoint location = getCurrentWorldLocation();
        return location == null ? 0 : location.getPlane();
    }

    private int getCurrentRegionId()
    {
        WorldPoint location = getCurrentWorldLocation();
        return location == null ? -1 : location.getRegionID();
    }

    private WorldPoint getCurrentWorldLocation()
    {
        Player localPlayer = client.getLocalPlayer();
        return localPlayer == null ? null : localPlayer.getWorldLocation();
    }

    private void resetForCollectedReward()
    {
        resetCounts();
        engagedNpcs.clear();
        rewardCollected = true;
        configManager.unsetRSProfileConfiguration(
            BarrowsTunnelsKillTrackerConfig.GROUP,
            KILL_COUNTS_CONFIG_KEY);
    }

    private void resetCounts()
    {
        killCounts.clear();

        for (TrackedNpc trackedNpc : TrackedNpc.values())
        {
            killCounts.put(trackedNpc, 0);
        }
    }

    private void loadPersistedKillCounts()
    {
        resetCounts();

        String persistedKillCounts = configManager.getRSProfileConfiguration(
            BarrowsTunnelsKillTrackerConfig.GROUP,
            KILL_COUNTS_CONFIG_KEY);

        if (persistedKillCounts == null || persistedKillCounts.trim().isEmpty())
        {
            return;
        }

        boolean shouldRewrite = false;

        for (String entry : persistedKillCounts.split(","))
        {
            String[] parts = entry.split("=", 2);
            if (parts.length != 2)
            {
                shouldRewrite = true;
                continue;
            }

            try
            {
                TrackedNpc trackedNpc = TrackedNpc.valueOf(parts[0].trim());
                int count = Integer.parseInt(parts[1].trim());

                if (count > 0)
                {
                    killCounts.put(trackedNpc, count);
                }
                else
                {
                    shouldRewrite = true;
                }
            }
            catch (IllegalArgumentException ex)
            {
                shouldRewrite = true;
            }
        }

        if (shouldRewrite)
        {
            persistKillCounts();
        }
    }

    private void persistKillCounts()
    {
        StringBuilder value = new StringBuilder();

        for (TrackedNpc trackedNpc : TrackedNpc.values())
        {
            int count = killCounts.getOrDefault(trackedNpc, 0);
            if (count <= 0)
            {
                continue;
            }

            if (value.length() > 0)
            {
                value.append(',');
            }

            value.append(trackedNpc.name())
                .append('=')
                .append(count);
        }

        if (value.length() == 0)
        {
            configManager.unsetRSProfileConfiguration(
                BarrowsTunnelsKillTrackerConfig.GROUP,
                KILL_COUNTS_CONFIG_KEY);
            return;
        }

        configManager.setRSProfileConfiguration(
            BarrowsTunnelsKillTrackerConfig.GROUP,
            KILL_COUNTS_CONFIG_KEY,
            value.toString());
    }
}

package com.barrowstunnelskilltracker;

import java.util.HashMap;
import java.util.Map;

enum TrackedNpc
{
    BLOODWORM("Bloodworm", 1678),
    CRYPT_RAT("Crypt rat", 1679),
    GIANT_CRYPT_RAT("Giant crypt rat", 1680, 1681, 1682),
    CRYPT_SPIDER("Crypt spider", 1683),
    GIANT_CRYPT_SPIDER("Giant crypt spider", 1684),
    SKELETON("Skeleton", 1685, 1686, 1687, 1688);

    private static final Map<Integer, TrackedNpc> NPCS_BY_ID = new HashMap<>();

    static
    {
        for (TrackedNpc trackedNpc : values())
        {
            for (int npcId : trackedNpc.npcIds)
            {
                NPCS_BY_ID.put(npcId, trackedNpc);
            }
        }
    }

    private final String displayName;
    private final int[] npcIds;

    TrackedNpc(String displayName, int... npcIds)
    {
        this.displayName = displayName;
        this.npcIds = npcIds;
    }

    String getDisplayName()
    {
        return displayName;
    }

    static TrackedNpc fromNpcId(int npcId)
    {
        return NPCS_BY_ID.get(npcId);
    }
}

